import json,re,collections
recs=[json.loads(l) for l in open('corpus.jsonl')]
sup=[r for r in recs if r['dir']=='SUP']
pat=re.compile(r'\b(could you|would you|please|send|confirm|share|provide|need|require|commit|forecast|we would|we need|if you|if we|we can|we could|how about|maybe|target|in return|willing|consider|happy to|a middle|meet|bridge)\b',re.I)
c=collections.Counter(); ex={}
for r in sup:
    for line in r['text'].split('\n'):
        for s in re.split(r'(?<=[.?!])\s+',line):
            s=s.strip()
            if pat.search(s) and '?' not in s:
                k=re.sub(r'[0-9.,%€]+','N',s)[:160]
                c[k]+=1; ex.setdefault(k,(r['case'],r['sup'][4:],r['session'][:8]))
for k,v in c.most_common(200): print(v,ex[k][0],ex[k][1],'|',k)
