cd /private/tmp/claude-501/-Users-stef-Projects-ehlcodacabana-final/daf2a093-2bd0-4ce9-80b9-341ae1b7774e/scratchpad && cat > classify.py <<'EOF'
import json,re,collections
recs=[json.loads(l) for l in open('corpus.jsonl')]
# group threads in order
threads=collections.defaultdict(list)
for r in recs:
    if r['dir']=='SUP' or (r['dir']=='BUY' and r['sup']):
        threads[(r['session'],r['sup'])].append(r)
def sents(t):
    out=[]
    for line in t.split('\n'):
        for s in re.split(r'(?<=[.?!])\s+',line):
            if s.strip(): out.append(s.strip())
    return out
ASK={
 'volume_commit': r'(volume|commit)',
 'forecast_proof': r'(proof|concrete|binding|evidence|data|figures?)\b.*\b(forecast|volume|demand)|\b(forecast|volume)\b.*\b(proof|confirm|concrete|binding|share)',
 'basis_of_figures': r'(figures|based on|basis|calculation)\b.*\?|\?.*(figures|based on|basis)',
 'confirm_or_decide': r'(let (me|us) know|confirm|decide|agree|deal|go with|are we good|wrap|lock this in|if this works|move forward)',
 'payment_term_ask': r'(payment|paid|zahlungsziel|days)\b.*\b(can you|could you|would you|accept|agree|consider|offer)',
 'lead_time_ask': r'(lead time|delivery time|lieferzeit)',
 'contract_ask': r'(contract|months|term)\b.*\b(can you|could you|would you|commit|accept|agree)',
 'cost_breakdown_req': r'(breakdown|cost structure|cost details)',
 'other_question': r'.',
}
def classify(s):
    sl=s.lower(); cats=[]
    isq='?' in s
    if re.search(r'volume',sl) and (isq or re.search(r'\b(please|could|tell|give|confirm|specify|share|provide|let us know|let me know)\b',sl)) and not re.search(r'(we|our) (are|can|will|would|have)|we (can|will) (do|offer)|we (can|will) commit',sl):
        cats.append('volume_commit')
    if re.search(r'(proof|concrete|binding|evidence)',sl) and re.search(r'(forecast|volume|demand)',sl): cats.append('forecast_proof')
    if isq and re.search(r'(figures|based on|basis|calculation|how did you|source)',sl): cats.append('basis_of_figures')
    if re.search(r'(let (me|us) know|confirm|decide|are we good|let\'?s wrap|lock this in|let me know if we have a deal|if this works|so we can (get|finalize|proceed|move forward|plan))',sl) and not re.search(r'we (can|will) (confirm|agree)',sl): cats.append('close_or_confirm_ask')
    if re.search(r'(payment|zahlungsziel|paid)',sl) and isq: cats.append('payment_ask')
    if re.search(r'(lead time|lieferzeit|delivery time)',sl) and isq: cats.append('leadtime_ask')
    if re.search(r'(contract|months|commitment|term)',sl) and isq and not 'payment' in sl: cats.append('contract_ask')
    if re.search(r'(breakdown|cost structure|cost details|share)',sl) and re.search(r'(please|could|would|send|share|provide)',sl) and re.search(r'(send|share|provide|would you|could you)',sl) and 'do not share' not in sl and "don't share" not in sl and 'not share' not in sl and 'cannot be shared' not in sl and 'do not disclose' not in sl and 'not permit' not in sl and 'confidential' not in sl and 'share' in sl and isq: cats.append('breakdown_or_data_ask')
    if isq and not cats: cats.append('other_q')
    return cats
ans_kw={
 'volume_commit': r'(\d[\d,.]*\s*(units|pcs|pieces|per year|/year|a year|p\.a|annual))|(annual|yearly|per year|volume (of|is|will be|forecast))|\b\d{3,}\b',
}
counts=collections.Counter(); ex={}
results=[]
for key,msgs in threads.items():
    for i,r in enumerate(msgs):
        if r['dir']!='SUP': continue
        nxt=next((m for m in msgs[i+1:] if m['dir']=='BUY' and m['status']=='message'),None)
        for s in sents(r['text']):
            for c in classify(s):
                if c=='other_q' and False: pass
                # answered?
                ans=None
                if nxt is not None:
                    bt=nxt['text']
                    if c=='volume_commit':
                        ans=bool(re.search(r'(volume|forecast|annual|per year)',bt,re.I)) and bool(re.search(r'\d',bt))
                    elif c=='forecast_proof':
                        ans=bool(re.search(r'(forecast|volume)',bt,re.I))
                    elif c=='basis_of_figures':
                        ans=bool(re.search(r'(should-cost|cost:|idx:|doc:|ctr:)',bt))
                    elif c=='close_or_confirm_ask':
                        ans=bool(re.search(r'(accept|agree|confirm|deal|order)',bt,re.I))
                    elif c=='payment_ask':
                        ans=bool(re.search(r'payment \d+ days|\d+ days (net|payment)',bt,re.I))
                    elif c=='leadtime_ask':
                        ans=bool(re.search(r'lead time',bt,re.I))
                    elif c=='contract_ask':
                        ans=bool(re.search(r'(contract|months)',bt,re.I))
                    elif c=='breakdown_or_data_ask':
                        ans=bool(re.search(r'(doc:|cost:|idx:|ctr:)',bt))
                    else: ans=None
                k=(c)
                counts[k]+=1
                results.append(dict(cat=c,case=r['case'],sup=r['sup'][4:],session=r['session'][:8],round=r['round'],sent=s,answered=ans,status=r['status']))
import pickle
json.dump(results,open('asks.json','w'),ensure_ascii=False)
for k,v in counts.most_common(): 
    rs=[x for x in results if x['cat']==k]
    a=sum(1 for x in rs if x['answered'] is True); n=sum(1 for x in rs if x['answered'] is None)
    cs=collections.Counter(x['case'] for x in rs)
    print(f"{k}: n={v} answered_next={a} na={n} cases={dict(cs.most_common(4))}")
EOF
