trade=re.compile(r'(if you|if we|should you|in return|in exchange|for a better|in order to|to move further|to consider|to offer you|to offer a more|would need|we would require|we need (a|bigger|more|to)|you have to|help us|meet you|middle|would help|can improve|can reflect|faster payment|tell me what volume|give us a solid|bigger volumes?|higher volumes?|longer (contract|term)|as long as|provided|once you|needs? (approval|movement))',re.I)
excl=re.compile(r'^(Our terms|Our current|Our Angebot|Our offer|Our price follows|Our standard|Our Lieferzeit|Option|- Option|Alternatively)',re.I)
lev={'volume':r'volume','contract length':r'(contract|months?\b|term\b|duration)','payment speed':r'(faster payment|paid faster|pay(ing)? faster|payment (in|within) \d+|\d+ days? (payment|net)|pay(ment)? sooner|getting paid|cash)','lead time':r'(lead ?time|Lieferzeit|delivery time|overtime|\d+ days lead)','quality ppm':r'ppm|chargeback','index/deadband':r'(deadband|Preisgleitklausel|index)','incoterm/DAP':r'(DAP|EXW|FCA|incoterm|delivery terms)','partnership/relationship':r'(relationship|partnership|long-standing)'}
c=collections.Counter(); th=collections.defaultdict(set); cs=collections.defaultdict(collections.Counter); ex={}
for r in sup:
    for line in r['text'].split('\n'):
        for s in re.split(r'(?<=[.?!])\s+',line):
            s=s.strip()
            if excl.search(s) or not trade.search(s): continue
            for k,p in lev.items():
                if re.search(p,s,re.I):
                    c[k]+=1; th[k].add((r['session'][:8],r['sup'][4:])); cs[k][r['case']]+=1; ex.setdefault(k,(r['case'],r['sup'][4:],re.sub(r'[0-9.,%€]+','N',s)[:130]))
for k in lev: print(f'{k}: sentences={c[k]} threads={len(th[k])} cases={dict(cs[k].most_common(4))} ex={ex.get(k)}')
"

